def make(index, row):
    tag, prompt, options, answer, explanation = row
    opts = [{"id": chr(65 + i), "text": text} for i, text in enumerate(options)]; aid = next(x["id"] for x in opts if x["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題以生活數據、替代方案、計算與公共分配考查經濟推理；本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」以及已選方案、未選方案、資源限制、數值與比較單位。", f"列出可行方案：先排序未選方案的價值，排除已經無法改變的沉沒成本與不相關數字；本題核心是「{explanation}」", f"計算或核對：選項 {aid}「{answer}」是依題幹數值與次佳方案判定得到的答案。", "排除誘答：檢查是否把所有未選方案相加、把選定方案支出、總預算或差額直接當成機會成本。", "結論回查：確認單位一致、算式可重做，並標記公平、資料不足或其他不能只靠數值決定的因素。"]
    return {"id": f"question-social-content-civ-bl-iv-2-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-civ-bl-iv-2"], "difficulty": "medium", "answer": {"value": aid, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "國立卓蘭高中附設國中部公開社會課程計畫；本題只研究公開試題與課程評量的能力結構。", "authoringNote": "依官方課綱、單元 KG、三個公立學校公開來源的題型方向，獨立改寫次佳方案、單位換算、總成本、沉沒成本、時間與產量計算、條件變化、公共預算、公平與資料不足；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-civ-bl-iv-2", "examPatternRefs": refs, "solutionStrategy": "先列出限制與可行方案，再依價值排序找出次佳方案，固定單位並計算放棄的價值，最後分辨沉沒成本與公平、資料不足等不能只用數字判斷的因素。", "solutionSteps": steps}

for i, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-civ-bl-iv-2-{i}.json").write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
